const rankingsData=window.UHC_RANKINGS;
const teamAnchor=color=>'team-color-'+encodeURIComponent(color);
const ratio=(n,d)=>`${n} / ${d}`;
const percent=n=>(100*n).toFixed(1)+'%';
function teamCard(team){
 const reason=team.isColor?`${team.appearances} of 6 required appearances`:'Special grouping; not a team color';
 return `<article class="team-ranking-card" id="${teamAnchor(team.color)}" style="--team:${colors[team.color]||'#a3ad9e'}"><header class="team-ranking-header"><div class="team-swatch ${team.color==='Mole'?'mole-color':''}" style="${team.color==='Mole'?molePaint():''}"></div><div><p class="eyebrow">${team.eligible?'COLOR RANK #'+team.rank:'UNRANKED'}</p><h2>${escape(teamDisplayName(team.color))}<span>.</span></h2><p>${team.appearances} appearances · ${team.uniquePlayers} distinct players${team.eligible?'':' · '+escape(reason)}</p></div><div class="team-score">${team.eligible?`<strong>${team.score.toFixed(2)}</strong><span>PERFORMANCE SCORE / 100</span>`:'<span>HISTORY AVAILABLE</span>'}</div></header><div class="team-metrics"><div><b>${percent(team.winRate)}</b><span>WIN RATE</span><small>${ratio(team.wins,team.appearances)} wins / appearances</small></div><div><b>${team.killsPerParticipant.toFixed(2)}</b><span>KILLS / PARTICIPANT</span><small>${ratio(team.kills,team.participants)} kills / entries</small></div><div><b>${percent(team.survivalRate)}</b><span>SURVIVAL RATE</span><small>${ratio(team.survivors,team.participants)} survivors / entries</small></div><div><b>${team.ironmen}</b><span>IRONMEN</span><small>${team.teamKills} Team Kills committed</small></div></div><details class="team-detail-notes"><summary>Score breakdown and other stats</summary>${team.eligible?`<p>Win contribution: ${team.components.win.toFixed(2)} / 60 · Combat: ${team.components.combat.toFixed(2)} / 25 · Survival: ${team.components.survival.toFixed(2)} / 15.</p>`:''}<p>${team.participants} participant entries · ${team.pvpDeaths} PVP deaths · ${team.pveDeaths} PVE deaths · ${team.teamKillDeaths} Team Kill deaths · ${team.otherExits} other exits.</p></details><div class="table-wrap"><table class="team-history"><caption>${escape(teamDisplayName(team.color))} appearances</caption><thead><tr><th>Season / date</th><th>Team name</th><th>Players</th><th>Result</th><th>PVP kills</th><th>Survivors</th></tr></thead><tbody>${team.history.map(h=>`<tr class="${team.color==='Mole'?'mole-row':''}" style="${team.color==='Mole'?molePaint(h.season):''}"><td><a href="#season-${h.season}">S${h.season}</a><small>${escape(h.date)}</small></td><td>${escape(h.teams.map(teamDisplayName).join(' · ')||'None')}</td><td>${h.players.map(n=>`<span class="stat-person">${statPlayer(n)}</span>`).join('')}</td><td>${h.win?'<span class="badge iron">Victory</span>':'—'}</td><td>${h.kills}</td><td>${h.survivors} / ${h.participants}</td></tr>`).join('')}</tbody></table></div></article>`;
}
function rankingTeams(){
 const query=$('ranking-search').value.trim().toLowerCase(),filter=$('ranking-filter').value,sort=$('ranking-order').value;
 return rankingsData.teams.filter(t=>(filter!=='ranked'||t.eligible)&&(filter!=='unranked'||!t.eligible)&&(!query||t.color.toLowerCase().includes(query)||t.history.some(h=>h.teams.some(n=>n.toLowerCase().includes(query))||h.players.some(n=>n.toLowerCase().includes(query))||query===`s${h.season}`||query===`season ${h.season}`||query===String(h.season)))).sort((a,b)=>sort==='wins'?b.winRate-a.winRate||b.appearances-a.appearances:sort==='kills'?b.killsPerParticipant-a.killsPerParticipant:sort==='appearances'?b.appearances-a.appearances:sort==='name'?a.color.localeCompare(b.color):(a.rank??Infinity)-(b.rank??Infinity)||b.appearances-a.appearances||a.color.localeCompare(b.color));
}
function renderRankings(){
 const teams=rankingTeams();$('ranking-result-count').textContent=`${teams.length} of ${rankingsData.teams.length} colors / groupings`;
 $('ranking-index').innerHTML=[...rankingsData.teams].sort((a,b)=>Number(a.color==='Not recorded')-Number(b.color==='Not recorded')).map(t=>`<a href="#${teamAnchor(t.color)}" class="${teams.includes(t)?'':'filtered'}"><i class="${t.color==='Mole'?'mole-color':''}" style="${t.color==='Mole'?molePaint():''}background:${colors[t.color]||'#a3ad9e'}"></i>${escape(teamDisplayName(t.color))}<span>${t.rank?'#'+t.rank:'—'}</span></a>`).join('');
 $('ranking-list').innerHTML=teams.map(teamCard).join('')||'<div class="empty">No colors match your search.</div>';
}
function rankingsRoute(){const mode=location.hash==='#rankings-players'||location.hash.startsWith('#rank-player-')?'players':'teams';switchRankingsMode(mode);if(mode==='players'){if(location.hash.startsWith('#rank-player-')){let name;try{name=decodeURIComponent(location.hash.slice(13))}catch{return}const player=playerRankingData.players.find(p=>p.name===profileIdentity(name));if(player){$('pr-search').value='';$('pr-tier-filter').value='all';renderPlayerRankings();requestAnimationFrame(()=>{const row=document.getElementById(rankingPlayerAnchor(player.name));if(row){row.open=true;row.scrollIntoView();}});}}return;}renderRankings();if(location.hash.startsWith('#team-color-')){let color;try{color=decodeURIComponent(location.hash.slice(12))}catch{return}const team=rankingsData.teams.find(t=>t.color===color);if(!team)return;if(!rankingTeams().some(t=>t.color===color)){$('ranking-search').value='';$('ranking-filter').value='all';renderRankings();}requestAnimationFrame(()=>document.getElementById(teamAnchor(color))?.scrollIntoView());}}
function initializeRankings(){
 const help=$('ranking-help-dialog');
 $('ranking-help').addEventListener('click',()=>help.showModal());
 help.addEventListener('click',e=>{
  if(e.target!==help)return;
  const r=help.getBoundingClientRect();
  if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)help.close();
 });
 $('ranking-search').addEventListener('input',renderRankings);$('ranking-filter').addEventListener('change',renderRankings);$('ranking-order').addEventListener('change',renderRankings);
 $('ranking-reset').addEventListener('click',()=>{$('ranking-search').value='';$('ranking-filter').value='all';$('ranking-order').value='rank';renderRankings();});
 $('ranking-method').textContent=rankingsData.method;$('ranking-notes').textContent=rankingsData.notes;
 $('ranking-summary').textContent=`${rankingsData.teams.filter(t=>t.eligible).length} ranked colors · Six appearances required`;
}
